const BASE_TYPE_ALLOWANCE = 3;

const SPHINX_BASE_POINTS = 1;

const BASE_BONUS = 1;

const POINTS_PER_EXTRA_TYPE = 2;

const scorePerSphinx = (monsterTypes: number): number => {
  const nonSphinxTypes = monsterTypes - 1;
  const extraTypes = nonSphinxTypes - BASE_TYPE_ALLOWANCE;
  const bonus = extraTypes > 0 ? POINTS_PER_EXTRA_TYPE * extraTypes : BASE_BONUS;
  return SPHINX_BASE_POINTS + bonus;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxes = countSphinxes(army);
  if (sphinxes === 0) return 0;
  return sphinxes * scorePerSphinx(countDistinctMonsterTypes(army));
};
